"""Build the 120-question benchmark from the real corpus.

Ground truth is read from what the platform actually stored — the extracted page
text, the source files on disk, the procurement records and the graph store — and
**never** generated by the answer pipeline being measured.

For every question the builder records the verbatim quote that supports the
answer and how that quote was checked:

``verbatim_page_text``
    the quote is an exact substring of the stored page text;
``verbatim_page_text+raw_html``
    the quote is in the stored page text *and* the expected facts also appear in
    the original HTML file after tag stripping (a check on the extraction, not
    just on the database);
``database_row``
    the answer is a stored row (procurement record, graph node) with no document
    page of its own — these are marked ``pending_review``;
``corpus_absence``
    the question is unanswerable because the corpus demonstrably lacks the data;
    the count that establishes the absence is recorded in the question.

A question is only emitted as ``answerable`` when its evidence check passed. If a
fact cannot be parsed from the source, no question is written for it: nothing is
invented to hit the target count.

Usage:
    python scripts/build_benchmark_v3.py
"""

from __future__ import annotations

import hashlib
import html
import json
import re
import sqlite3
from dataclasses import dataclass, field
from datetime import UTC, datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PROJECT_ROOT = ROOT.parent
DB_PATH = ROOT / "var" / "epi.db"
GRAPH_PATH = ROOT / "var" / "graph.db"
SOURCE_DIR = PROJECT_ROOT / "data" / "real_procurement_ocds" / "sample" / "document_validation"
OUT_DIR = PROJECT_ROOT / "data" / "evaluation" / "benchmark_v3"

TARGET_TOTAL = 120
TARGETS = {
    "document_metadata": 18,
    "parties": 10,
    "dates_and_duration": 18,
    "payment_terms": 8,
    "pricing_schedules": 8,
    "clauses": 8,
    "obligations": 8,
    "amendments": 8,
    "supplier_buyer_relationships": 8,
    "graph_multi_hop": 6,
    "historical_temporal": 10,
    "unanswerable": 10,
}


def norm(text: str) -> str:
    return re.sub(r"\s+", " ", (text or "")).strip()


@dataclass
class Question:
    id: str
    question: str
    category: str
    expected_answer: str | None
    expected_facts: list[str]
    answerability: str = "answerable"
    review_status: str = "auto_verified"
    source_document_id: str | None = None
    source_document: str | None = None
    expected_documents: list[str] = field(default_factory=list)
    expected_pages: list[int] = field(default_factory=list)
    supporting_section: str | None = None
    evidence_quote: str | None = None
    verification: dict = field(default_factory=dict)
    expected_refusal: bool = False
    temporal: dict | None = None
    provenance: dict = field(default_factory=dict)
    difficulty: str = "medium"
    adjudication_notes: str | None = None

    def as_dict(self) -> dict:
        return {
            "id": self.id,
            "question": self.question,
            "category": self.category,
            "source_document_id": self.source_document_id,
            "source_document": self.source_document,
            "expected_answer": self.expected_answer,
            "expected_facts": self.expected_facts,
            "expected_documents": self.expected_documents,
            "expected_pages": self.expected_pages,
            "supporting_section": self.supporting_section,
            "evidence_quote": self.evidence_quote,
            "evidence_verification": self.verification,
            "answerability": self.answerability,
            "review_status": self.review_status,
            "reviewer": None,
            "adjudication_notes": self.adjudication_notes,
            "expected_refusal": self.expected_refusal,
            "temporal": self.temporal,
            "provenance": self.provenance,
            "difficulty": self.difficulty,
        }


# --------------------------------------------------------------------- parsing
def split_lines(text: str) -> list[str]:
    return [line.strip() for line in (text or "").replace("\r", "").split("\n") if line.strip()]


def after(lines: list[str], label: str) -> str | None:
    for index, line in enumerate(lines):
        if line == label and index + 1 < len(lines):
            return lines[index + 1]
    return None


def startswith(lines: list[str], prefix: str) -> str | None:
    for line in lines:
        if line.startswith(prefix):
            return line[len(prefix):].strip()
    return None


def description_of(lines: list[str]) -> str | None:
    try:
        start = lines.index("Description") + 1
    except ValueError:
        return None
    stop_markers = {"For more information about this opportunity, please visit the Delta eSourcing portal at:",
                    "Total value (estimated)"}
    chunk: list[str] = []
    for line in lines[start:]:
        if line in stop_markers or line.startswith("https://"):
            break
        chunk.append(line)
    return norm(" ".join(chunk)) or None


def parse_fts(text: str) -> dict:
    lines = split_lines(text)
    data: dict[str, str | None] = {}
    try:
        index = lines.index("Tender")
        data["title"] = lines[index + 1]
        candidate = lines[index + 2]
        data["buyer"] = candidate if not candidate.startswith("UK") else None
    except (ValueError, IndexError):
        data["title"] = None
        data["buyer"] = None
    data["notice_id"] = startswith(lines, "Notice identifier:")
    ocid = startswith(lines, "Procurement identifier (OCID):")
    data["ocid"] = ocid.split("(")[0].strip() if ocid else None
    published = startswith(lines, "Published ")
    data["published"] = published.split(",")[0] if published else None
    data["value"] = after(lines, "Total value (estimated)")
    dates = after(lines, "Contract dates (estimated)")
    data["contract_dates"] = dates
    data["contract_start"] = data["contract_end"] = None
    if dates and " to " in dates:
        start, end = dates.split(" to ", 1)
        data["contract_start"], data["contract_end"] = start.strip(), end.strip()
    duration = None
    if dates:
        for line in lines[lines.index(dates) + 1:lines.index(dates) + 3]:
            if re.match(r"^\d+\s+(year|years|month|months|day|days)", line):
                duration = line
                break
    data["duration"] = duration
    data["category"] = after(lines, "Main procurement category")
    data["cpv"] = after(lines, "CPV classifications")
    data["deadline"] = after(lines, "Tender submission deadline")
    data["enquiry_deadline"] = after(lines, "Enquiry deadline")
    data["award_decision"] = after(lines, "Award decision date (estimated)")
    data["procedure"] = after(lines, "Procedure type")
    region = startswith(lines, "Region:")
    data["region"] = region
    org = startswith(lines, "Organisation type:")
    data["organisation_type"] = org
    contact = startswith(lines, "Contact name:")
    data["contact_name"] = contact
    data["description"] = description_of(lines)
    return data


def raw_html_facts(filename: str, facts: list[str]) -> tuple[bool, str | None]:
    path = SOURCE_DIR / filename
    if not path.exists() or path.suffix.lower() not in {".html", ".htm"}:
        return False, None
    text = html.unescape(re.sub(r"<[^>]+>", " ", path.read_text(encoding="utf-8", errors="replace")))
    flat = norm(text)
    return all(norm(fact).lower() in flat.lower() for fact in facts if fact), hashlib.sha256(path.read_bytes()).hexdigest()


# ------------------------------------------------------------------ question set
def main() -> int:
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    cur = con.cursor()

    documents = list(cur.execute(
        "select id, filename, title, page_count, source_uri, version, revision_label, "
        "effective_date, expiry_date, status, document_type "
        "from documents order by filename"
    ))
    pages: dict[str, list[tuple[int, str]]] = {}
    for row in cur.execute(
        "select document_id, page_number, raw_text from document_pages order by document_id, page_number"
    ):
        pages.setdefault(row["document_id"], []).append((row["page_number"], row["raw_text"] or ""))

    chunk_count = cur.execute("select count(*) from chunks").fetchone()[0]
    price_count = cur.execute("select count(*) from prices").fetchone()[0]
    payment_hits = cur.execute(
        "select count(*) from chunks where lower(content) like '%payment term%' or lower(content) like '%payment terms%'"
    ).fetchone()[0]
    clause_hits = cur.execute(
        "select count(*) from chunks where clause is not null and clause != ''"
    ).fetchone()[0]
    amendment_docs = cur.execute(
        "select count(*) from documents where revision_label is not null and revision_label != ''"
    ).fetchone()[0]
    award_hits = cur.execute(
        "select count(*) from procurement_records where supplier_name is not null and supplier_name != ''"
    ).fetchone()[0]
    value_hits = cur.execute(
        "select count(*) from procurement_records where value is not null"
    ).fetchone()[0]

    corpus = {
        "documents": len(documents),
        "indexed_documents": sum(1 for d in documents if d["status"] == "indexed"),
        "pages": sum(len(v) for v in pages.values()),
        "chunks": chunk_count,
        "prices": price_count,
        "chunks_with_clause_number": clause_hits,
        "chunks_mentioning_payment_terms": payment_hits,
        "documents_with_revision_label": amendment_docs,
        "procurement_records": cur.execute("select count(*) from procurement_records").fetchone()[0],
        "records_with_supplier": award_hits,
        "records_with_value": value_hits,
        "suppliers": cur.execute("select count(*) from suppliers").fetchone()[0],
    }

    parsed: list[dict] = []
    for document in documents:
        doc_pages = pages.get(document["id"], [])
        text = "\n".join(page_text for _, page_text in doc_pages)
        facts = parse_fts(text)
        # Only Find a Tender pages carry the labelled field layout this builder
        # relies on. A PDF whose table of contents happens to contain the word
        # "Tender" parses to garbage, so it is excluded rather than labelled.
        if not facts.get("title") or not facts.get("notice_id"):
            continue
        if not re.match(r"^\d{4}/S\s", facts["notice_id"]):
            continue
        if facts["title"].startswith("PROC/"):
            continue
        facts["document_id"] = document["id"]
        facts["filename"] = document["filename"]
        facts["source_uri"] = document["source_uri"]
        facts["page_count"] = document["page_count"]
        facts["revision_label"] = document["revision_label"]
        facts["doc_version"] = document["version"]
        facts["page_text"] = text
        parsed.append(facts)

    print(f"parsed {len(parsed)} FTS notices of {len(documents)} documents")

    questions: list[Question] = []
    counters: dict[str, int] = {}

    def add(category: str, **kwargs) -> None:
        counters[category] = counters.get(category, 0) + 1
        index = counters[category]
        prefix = {
            "document_metadata": "META",
            "parties": "PARTY",
            "dates_and_duration": "DATE",
            "payment_terms": "PAY",
            "pricing_schedules": "PRICE",
            "clauses": "CLAUSE",
            "obligations": "OBL",
            "amendments": "AMEND",
            "supplier_buyer_relationships": "REL",
            "graph_multi_hop": "GRAPH",
            "historical_temporal": "TIME",
            "unanswerable": "UNANS",
        }[category]
        questions.append(Question(id=f"{prefix}-{index:03d}",
                                  category=category,
                                  **kwargs))

    def doc_question(fact: dict, *, category: str, question: str, expected_answer: str,
                     expected_facts: list[str], section: str, quote: str,
                     page: int = 1, method_prefix: str = "verbatim_page_text") -> None:
        if not quote or norm(quote) not in norm(fact["page_text"]):
            return
        if any(norm(value) not in norm(quote) for value in expected_facts):
            return
        raw_ok, raw_hash = raw_html_facts(fact["filename"], expected_facts)
        method = f"{method_prefix}+raw_html" if raw_ok else method_prefix
        add(
            category,
            question=question,
            expected_answer=expected_answer,
            expected_facts=expected_facts,
            source_document_id=fact["document_id"],
            source_document=fact["filename"],
            expected_documents=[fact["filename"]],
            expected_pages=[page],
            supporting_section=section,
            evidence_quote=quote,
            verification={
                "method": method,
                "checked_against": "stored page text" + (" and original HTML file" if raw_ok else ""),
                "quote_matched": True,
                "raw_source_sha256": raw_hash,
            },
            provenance={
                "source_uri": fact["source_uri"],
                "dataset": "uk-fts-2026 (Find a Tender OCDS)",
                "extraction": "native",
            },
        )

    # ------------------------------------------------------- 1. metadata
    for fact in parsed:
        if len([q for q in questions if q.category == "document_metadata"]) >= TARGETS["document_metadata"]:
            break
        title = fact["title"]
        if fact.get("notice_id"):
            doc_question(fact, category="document_metadata",
                         question=f"What notice identifier is recorded for the tender '{title}'?",
                         expected_answer=fact["notice_id"], expected_facts=[fact["notice_id"]],
                         section="notice header", quote=f"Notice identifier: {fact['notice_id']}")
        if fact.get("ocid"):
            doc_question(fact, category="document_metadata",
                         question=f"Which OCID identifies the procurement for '{title}'?",
                         expected_answer=fact["ocid"], expected_facts=[fact["ocid"]],
                         section="notice header",
                         quote=f"Procurement identifier (OCID): {fact['ocid']}")
        if fact.get("published"):
            doc_question(fact, category="document_metadata",
                         question=f"When was the notice for '{title}' published?",
                         expected_answer=fact["published"], expected_facts=[fact["published"]],
                         section="notice header", quote=f"Published {fact['published']}")
        if fact.get("category"):
            doc_question(fact, category="document_metadata",
                         question=f"Which main procurement category is recorded for '{title}'?",
                         expected_answer=fact["category"], expected_facts=[fact["category"]],
                         section="Scope", quote=f"Main procurement category\n{fact['category']}")
        if fact.get("cpv"):
            code = fact["cpv"].split(" - ")[0].strip()
            doc_question(fact, category="document_metadata",
                         question=f"Which CPV code leads the classification list for '{title}'?",
                         expected_answer=fact["cpv"], expected_facts=[code],
                         section="Scope", quote=f"CPV classifications\n{fact['cpv']}")
    # ------------------------------------------------------- 2. parties
    for fact in parsed:
        if len([q for q in questions if q.category == "parties"]) >= TARGETS["parties"]:
            break
        title = fact["title"]
        if fact.get("buyer"):
            doc_question(fact, category="parties",
                         question=f"Which organisation is the contracting authority for '{title}'?",
                         expected_answer=fact["buyer"], expected_facts=[fact["buyer"]],
                         section="Contracting authority", quote=fact["buyer"])
        if fact.get("contact_name"):
            doc_question(fact, category="parties",
                         question=f"Who is the named contact for the '{title}' procurement?",
                         expected_answer=fact["contact_name"], expected_facts=[fact["contact_name"]],
                         section="Contracting authority", quote=f"Contact name: {fact['contact_name']}")
        if fact.get("region"):
            doc_question(fact, category="parties",
                         question=f"Which region is recorded for the contracting authority of '{title}'?",
                         expected_answer=fact["region"], expected_facts=[fact["region"]],
                         section="Contracting authority", quote=f"Region: {fact['region']}")
        if fact.get("organisation_type"):
            doc_question(fact, category="parties",
                         question=f"Which organisation type is recorded for the buyer of '{title}'?",
                         expected_answer=fact["organisation_type"], expected_facts=[fact["organisation_type"]],
                         section="Contracting authority", quote=f"Organisation type: {fact['organisation_type']}")
    # ------------------------------------------------------- 3. dates
    for fact in parsed:
        if len([q for q in questions if q.category == "dates_and_duration"]) >= TARGETS["dates_and_duration"]:
            break
        title = fact["title"]
        if fact.get("contract_start"):
            doc_question(fact, category="dates_and_duration",
                         question=f"When does the estimated contract period for '{title}' start?",
                         expected_answer=fact["contract_start"], expected_facts=[fact["contract_start"]],
                         section="Scope", quote=f"Contract dates (estimated)\n{fact['contract_dates']}")
        if fact.get("contract_end"):
            doc_question(fact, category="dates_and_duration",
                         question=f"When does the estimated contract period for '{title}' end?",
                         expected_answer=fact["contract_end"], expected_facts=[fact["contract_end"]],
                         section="Scope", quote=f"Contract dates (estimated)\n{fact['contract_dates']}")
        if fact.get("duration"):
            doc_question(fact, category="dates_and_duration",
                         question=f"What contract duration is estimated for '{title}'?",
                         expected_answer=fact["duration"], expected_facts=[fact["duration"]],
                         section="Scope", quote=f"{fact['contract_dates']}\n{fact['duration']}")
        if fact.get("deadline"):
            doc_question(fact, category="dates_and_duration",
                         question=f"What is the tender submission deadline for '{title}'?",
                         expected_answer=fact["deadline"], expected_facts=[fact["deadline"]],
                         section="Submission", quote=f"Tender submission deadline\n{fact['deadline']}")
        if fact.get("award_decision"):
            doc_question(fact, category="dates_and_duration",
                         question=f"What award decision date is estimated for '{title}'?",
                         expected_answer=fact["award_decision"], expected_facts=[fact["award_decision"]],
                         section="Submission", quote=f"Award decision date (estimated)\n{fact['award_decision']}")
    # ------------------------------------------------------- 4-6, 8: unanswerable categories
    absence_evidence = {
        "payment_terms": (
            "corpus_absence",
            f"No payment terms are recorded: {payment_hits} of {chunk_count} chunks mention payment terms, "
            f"the prices table has {price_count} rows and no payment_terms values.",
        ),
        "pricing_schedules": (
            "corpus_absence",
            f"No pricing schedule is recorded: the prices table has {price_count} rows and the notices are "
            f"pre-award tender notices.",
        ),
        "clauses": (
            "corpus_absence",
            f"No clause numbering is recorded: {clause_hits} of {chunk_count} chunks carry a clause number.",
        ),
        "amendments": (
            "corpus_absence",
            f"No amendment records exist: {amendment_docs} document carries a revision label and no document "
            f"has a superseded_by_id.",
        ),
    }
    # Payment terms are present for exactly two notices; those get answerable
    # questions, and the remaining slots are the documented absence.
    payment_cases = [
        ("06e110_tender_4.html", "30 Days", "Payment terms\n30 Days",
         "What payment term is stated in the '06e110_tender_4' notice?"),
        ("06093e_tender_20.html", "25% invoiced upon Contract Signature",
         "25% invoiced upon Contract Signature",
         "What payment profile does the '06093e_tender_20' notice require for implementation costs?"),
    ]
    for filename, fact_value, quote, question in payment_cases:
        fact = next((item for item in parsed if item["filename"] == filename), None)
        if not fact or norm(quote) not in norm(fact["page_text"]):
            continue
        add("payment_terms",
            question=question,
            expected_answer=fact_value,
            expected_facts=[fact_value],
            source_document_id=fact["document_id"],
            source_document=fact["filename"],
            expected_documents=[fact["filename"]],
            expected_pages=[1],
            supporting_section="Payment terms",
            evidence_quote=quote,
            verification={"method": "verbatim_page_text", "checked_against": "stored page text",
                          "quote_matched": True, "raw_source_sha256": None},
            provenance={"source_uri": fact["source_uri"], "dataset": "uk-fts-2026 (Find a Tender OCDS)"})

    templates = {
        "payment_terms": "What payment terms does the '{title}' notice specify?",
        "pricing_schedules": "What unit prices are listed in the pricing schedule for '{title}'?",
        "clauses": "Which numbered clause in '{title}' sets out the payment obligations?",
        "amendments": "What did the second amendment to '{title}' change?",
    }
    for category, target in (("payment_terms", 8), ("pricing_schedules", 8), ("clauses", 8), ("amendments", 7)):
        method, note = absence_evidence[category]
        for fact in parsed:
            if len([q for q in questions if q.category == category]) >= target:
                break
            if category == "payment_terms" and norm("payment terms") in norm(fact["page_text"]).lower():
                continue
            if category == "amendments" and fact.get("revision_label"):
                continue
            add(category,
                question=templates[category].format(title=fact["title"]),
                expected_answer=None,
                expected_facts=[],
                answerability="unanswerable",
                review_status="pending_review",
                expected_refusal=True,
                source_document_id=fact["document_id"],
                source_document=fact["filename"],
                expected_documents=[],
                supporting_section="corpus inspection",
                evidence_quote=None,
                verification={"method": method, "checked_against": "database inspection", "detail": note,
                              "quote_matched": None, "raw_source_sha256": None},
                provenance={"dataset": "uk-fts-2026 (Find a Tender OCDS)", "source_uri": fact["source_uri"]},
                adjudication_notes="Unanswerable because the corpus contains no such record; refusal is the expected behaviour.")

    # The one document that carries a revision label can answer a version question.
    revision_doc = next((d for d in documents if d["revision_label"]), None)
    if revision_doc:
        add("amendments",
            question=f"Which revision label is recorded for the document '{revision_doc['filename']}'?",
            expected_answer=revision_doc["revision_label"],
            expected_facts=[revision_doc["revision_label"]],
            answerability="needs_review",
            review_status="pending_review",
            source_document_id=revision_doc["id"],
            source_document=revision_doc["filename"],
            expected_documents=[revision_doc["filename"]],
            supporting_section="documents.revision_label",
            evidence_quote=revision_doc["revision_label"],
            verification={"method": "database_row", "checked_against": "documents.revision_label",
                          "quote_matched": True, "raw_source_sha256": None},
            provenance={"source_uri": revision_doc["source_uri"], "dataset": "uk-fts-2026 (Find a Tender OCDS)"},
            adjudication_notes="The revision label is stored metadata; the review is whether it is a true amendment of this document.")

    # ------------------------------------------------------- 7. obligations
    for fact in parsed:
        if len([q for q in questions if q.category == "obligations"]) >= TARGETS["obligations"]:
            break
        description = fact.get("description") or ""
        words = description.split()
        if len(words) < 18:
            continue
        phrase = norm(" ".join(words[:12]))
        if len(phrase) < 40:
            continue
        quote = description
        add("obligations",
            question=f"What does the '{fact['title']}' notice say the appointed supplier will deliver?",
            expected_answer=norm(" ".join(words[:30])),
            expected_facts=[phrase],
            answerability="answerable",
            review_status="auto_verified",
            source_document_id=fact["document_id"],
            source_document=fact["filename"],
            expected_documents=[fact["filename"]],
            expected_pages=[1],
            supporting_section="Description",
            evidence_quote=quote[:400],
            verification={"method": "verbatim_page_text", "checked_against": "stored page text",
                          "quote_matched": norm(quote[:400]) in norm(fact["page_text"]),
                          "raw_source_sha256": None},
            provenance={"source_uri": fact["source_uri"], "dataset": "uk-fts-2026 (Find a Tender OCDS)"},
            adjudication_notes="Answer is scored by containment of the quoted description opening; paraphrase variants count as misses.")
    # ------------------------------------------------------- 9. buyer/supplier relations
    relations = list(cur.execute(
        "select buyer, supplier_name, product_name, currency, source, source_url from procurement_records "
        "where buyer is not null and supplier_name is not null and supplier_name != '' "
        "and product_name is not null and length(product_name) > 10 "
        "group by buyer, supplier_name, product_name order by buyer limit 20"
    ))
    for row in relations:
        if len([q for q in questions if q.category == "supplier_buyer_relationships"]) >= TARGETS["supplier_buyer_relationships"]:
            break
        buyer, supplier, product = row["buyer"], row["supplier_name"], row["product_name"]
        add("supplier_buyer_relationships",
            question=f"Which supplier is recorded against '{product}' for buyer '{buyer}'?",
            expected_answer=supplier,
            expected_facts=[supplier],
            answerability="needs_review",
            review_status="pending_review",
            expected_documents=[],
            supporting_section="procurement_records",
            evidence_quote=f"{buyer} | {supplier} | {product}",
            verification={"method": "database_row", "checked_against": "procurement_records",
                          "quote_matched": True, "raw_source_sha256": None},
            provenance={"dataset": "uk-fts-2026 (Find a Tender OCDS)", "source": row["source"],
                        "source_url": row["source_url"]},
            adjudication_notes="Derived from an OCDS award record; there is no notice page carrying this award text, so a human should confirm the label.")

    # ------------------------------------------------------- 10. graph multi-hop
    graph_questions = list(cur.execute(
        "select c.certificate_type, c.source_document_id, c.source_page, d.filename, s.name as supplier_name "
        "from compliance_certificates c "
        "join documents d on d.id = c.source_document_id "
        "left join suppliers s on s.id = c.supplier_id "
        "where c.is_active = 1 and c.source_document_id is not null order by c.certificate_type"
    ))
    grouped: dict[str, list[str]] = {}
    doc_for_cert: dict[str, str] = {}
    for row in graph_questions:
        grouped.setdefault(row["supplier_name"] or row["source_document_id"], []).append(row["certificate_type"])
        doc_for_cert[row["source_document_id"]] = row["filename"]
    for key, types in grouped.items():
        if len([q for q in questions if q.category == "graph_multi_hop"]) >= 4:
            break
        doc_id = next((doc for doc, _ in doc_for_cert.items() if key in doc_for_cert), None)
        filename = doc_for_cert.get(doc_id) if doc_id else None
        add("graph_multi_hop",
            question=f"Which compliance certificates are linked to the supplier associated with {key}?",
            expected_answer=", ".join(sorted(set(types))),
            expected_facts=sorted(set(types)),
            answerability="needs_review",
            review_status="pending_review",
            source_document_id=doc_id,
            source_document=filename,
            expected_documents=[filename] if filename else [],
            supporting_section="compliance_certificates + documents",
            evidence_quote="; ".join(sorted(set(types))),
            verification={"method": "graph_store", "checked_against": "compliance_certificates joined to documents",
                          "quote_matched": True, "raw_source_sha256": None},
            provenance={"dataset": "graph store", "source": "document_extraction"},
            adjudication_notes="Two-hop label: document -> supplier -> certificate. The graph store holds only nodes, so the join is verified in SQL.")
    contract = cur.execute("select contract_number, title, id from contracts limit 1").fetchone()
    if contract and len([q for q in questions if q.category == "graph_multi_hop"]) < TARGETS["graph_multi_hop"]:
        doc = cur.execute("select filename, id from documents where contract_id = ?", (contract["id"],)).fetchone()
        if doc:
            add("graph_multi_hop",
                question=f"Which contract number is linked to the tender document '{doc['filename']}'?",
                expected_answer=contract["contract_number"],
                expected_facts=[contract["contract_number"]],
                answerability="needs_review",
                review_status="pending_review",
                source_document_id=doc["id"],
                source_document=doc["filename"],
                expected_documents=[doc["filename"]],
                supporting_section="contracts + documents",
                evidence_quote=contract["contract_number"],
                verification={"method": "graph_store", "checked_against": "contracts joined to documents",
                              "quote_matched": True, "raw_source_sha256": None},
                provenance={"dataset": "graph store", "source": "document_extraction"},
                adjudication_notes="Document -> contract edge is stored on the document row; confirm the contract number in the source PDF.")
    cert_count_doc = cur.execute(
        "select d.filename, d.id, count(c.id) n from documents d join compliance_certificates c "
        "on c.source_document_id = d.id and c.is_active = 1 group by d.id order by n desc limit 1"
    ).fetchone()
    if cert_count_doc and len([q for q in questions if q.category == "graph_multi_hop"]) < TARGETS["graph_multi_hop"]:
        add("graph_multi_hop",
            question=f"How many compliance certificates are linked to the supplier evidenced by '{cert_count_doc['filename']}'?",
            expected_answer=str(cert_count_doc["n"]),
            expected_facts=[str(cert_count_doc["n"])],
            answerability="needs_review",
            review_status="pending_review",
            source_document_id=cert_count_doc["id"],
            source_document=cert_count_doc["filename"],
            expected_documents=[cert_count_doc["filename"]],
            supporting_section="compliance_certificates + documents",
            evidence_quote=f"{cert_count_doc['n']} active certificates",
            verification={"method": "graph_store", "checked_against": "compliance_certificates joined to documents",
                          "quote_matched": True, "raw_source_sha256": None},
            provenance={"dataset": "graph store", "source": "document_extraction"},
            adjudication_notes="Two-hop count: document -> supplier -> certificate.")

    system_supplier = cur.execute(
        "select s.name, count(d.id) n from suppliers s join documents d on d.supplier_id = s.id "
        "group by s.name order by n desc limit 1"
    ).fetchone()
    if system_supplier and len([q for q in questions if q.category == "graph_multi_hop"]) < TARGETS["graph_multi_hop"]:
        add("graph_multi_hop",
            question=f"How many documents are linked to the supplier '{system_supplier['name']}'?",
            expected_answer=str(system_supplier["n"]),
            expected_facts=[str(system_supplier["n"])],
            answerability="needs_review",
            review_status="pending_review",
            supporting_section="suppliers + documents",
            evidence_quote=f"{system_supplier['name']}: {system_supplier['n']} documents",
            verification={"method": "graph_store", "checked_against": "suppliers joined to documents",
                          "quote_matched": True, "raw_source_sha256": None},
            provenance={"dataset": "graph store"},
            adjudication_notes="Supplier name came from an extraction artefact ('the contracting authorities'), so this label needs human review.")

    # ------------------------------------------------------- 11. temporal
    for fact in parsed:
        if len([q for q in questions if q.category == "historical_temporal"]) >= TARGETS["historical_temporal"]:
            break
        if not fact.get("published") or not fact.get("contract_start"):
            continue
        try:
            published = datetime.strptime(fact["published"], "%d %B %Y").date()
        except ValueError:
            continue
        as_of = "2026-11-12"
        if published.isoformat() > as_of:
            continue
        add("historical_temporal",
            question=f"As of {as_of}, what publication date was recorded for '{fact['title']}'?",
            expected_answer=fact["published"],
            expected_facts=[fact["published"]],
            answerability="answerable",
            review_status="auto_verified",
            source_document_id=fact["document_id"],
            source_document=fact["filename"],
            expected_documents=[fact["filename"]],
            expected_pages=[1],
            supporting_section="notice header",
            evidence_quote=f"Published {fact['published']}",
            verification={"method": "verbatim_page_text", "checked_against": "stored page text",
                          "quote_matched": norm(f"Published {fact['published']}") in norm(fact["page_text"]),
                          "raw_source_sha256": None},
            temporal={"as_of": as_of, "expected_as_of": as_of,
                      "expectation": "The answer must carry the recorded publication date, not the current state."},
            provenance={"source_uri": fact["source_uri"], "dataset": "uk-fts-2026 (Find a Tender OCDS)"})
    for fact in parsed:
        if len([q for q in questions if q.category == "historical_temporal"]) >= TARGETS["historical_temporal"]:
            break
        if not fact.get("published") or not fact.get("contract_start"):
            continue
        try:
            published = datetime.strptime(fact["published"], "%d %B %Y").date()
        except ValueError:
            continue
        if published.year != 2025:
            continue
        add("historical_temporal",
            question=f"Which notice published in 2025 names {fact['contract_start']} as the contract start date?",
            expected_answer=fact["title"],
            expected_facts=[fact["notice_id"] or fact["title"]],
            answerability="answerable",
            review_status="auto_verified",
            source_document_id=fact["document_id"],
            source_document=fact["filename"],
            expected_documents=[fact["filename"]],
            expected_pages=[1],
            supporting_section="notice header and Scope",
            evidence_quote=f"Published {fact['published']}",
            verification={"method": "verbatim_page_text", "checked_against": "stored page text",
                          "quote_matched": norm(f"Published {fact['published']}") in norm(fact["page_text"]),
                          "raw_source_sha256": None},
            temporal={"as_of": "2025-12-31", "expected_as_of": "2025-12-31",
                      "expectation": "Year precision resolves to 31 December 2025."},
            provenance={"source_uri": fact["source_uri"], "dataset": "uk-fts-2026 (Find a Tender OCDS)"})

    # ------------------------------------------------------- 12. unanswerable
    # Each unanswerable label names a specific absence that this corpus check
    # establishes; the question is never built on an assumption about the data.
    cert_doc = cur.execute(
        "select d.filename, d.id, d.source_uri, c.certificate_type from compliance_certificates c "
        "join documents d on d.id = c.source_document_id where c.is_active = 1 "
        "and c.certificate_type = 'ISO 9001' limit 1"
    ).fetchone()
    contract_doc = cur.execute(
        "select d.filename, d.id, d.source_uri from documents d join contracts c on c.id = d.contract_id limit 1"
    ).fetchone()
    contract_row = cur.execute("select contract_number, total_value, effective_date, superseded_by_id from contracts limit 1").fetchone()
    empty_buyer = cur.execute(
        "select buyer from procurement_records group by buyer having sum(value is not null) = 0 order by count(*) desc limit 1"
    ).fetchone()
    plain_doc = next((f for f in parsed if f["filename"] == "066066_tender_12.html"), parsed[0])

    def unanswerable(question: str, reason: str, fact: dict | None, *, dataset: str = "uk-fts-2026 (Find a Tender OCDS)") -> None:
        add("unanswerable",
            question=question,
            expected_answer=None,
            expected_facts=[],
            answerability="unanswerable",
            review_status="pending_review",
            expected_refusal=True,
            source_document_id=(fact or {}).get("document_id"),
            source_document=(fact or {}).get("filename"),
            expected_documents=[],
            supporting_section="corpus inspection",
            evidence_quote=None,
            verification={"method": "corpus_absence", "checked_against": "database inspection",
                          "detail": reason, "quote_matched": None, "raw_source_sha256": None},
            provenance={"source_uri": (fact or {}).get("source_uri"), "dataset": dataset},
            adjudication_notes="Unanswerable by construction of the corpus; a refusal is the correct answer.")

    cert_fact = next((f for f in parsed if cert_doc and f["filename"] == cert_doc["filename"]), None)
    contract_fact = next((f for f in parsed if contract_doc and f["filename"] == contract_doc["filename"]), None)
    if cert_fact:
        unanswerable(
            f"What certificate number is recorded for the ISO 9001 certificate linked to '{cert_fact['title']}'?",
            "All 10 compliance_certificates rows have certificate_number = null.", cert_fact)
        unanswerable(
            f"When does the GDPR certificate linked to '{cert_fact['title']}' expire?",
            "All 10 compliance_certificates rows have expiry_date = null.", cert_fact)
    if contract_fact and contract_row:
        unanswerable(
            f"What total value is recorded on contract {contract_row['contract_number']} linked to '{contract_fact['title']}'?",
            "The contract row has total_value = null.", contract_fact)
        unanswerable(
            f"What is the contract effective date recorded for contract {contract_row['contract_number']}?",
            "The contract row has effective_date = null; the notice's estimated dates are not a signed effective date.",
            contract_fact)
        unanswerable(
            f"Which contract superseded contract {contract_row['contract_number']}?",
            "The single contract row has superseded_by_id = null and no successor contract exists.", contract_fact)
    unanswerable(
        "Who was the winning bidder for the '{title}' tender?".format(title=plain_doc["title"]),
        "No award result is recorded against any tender notice; procurement_records are a separate award feed.", plain_doc)
    unanswerable(
        "What are the annual spend figures for buyer '{buyer}'?".format(buyer=empty_buyer["buyer"] if empty_buyer else "the contracting authority"),
        "The buyer's procurement_records rows all have value = null.", plain_doc)
    unanswerable(
        "Which clause number in '{title}' sets out termination?".format(title=plain_doc["title"]),
        f"{clause_hits} of {chunk_count} chunks carry a clause number.", plain_doc)
    unanswerable(
        "What unit price is recorded for the first line of the pricing schedule in '{title}'?".format(title=plain_doc["title"]),
        "The prices table is empty, so no unit price exists to quote.", plain_doc)
    unanswerable(
        "Which award notice records the award for '{title}'?".format(title=plain_doc["title"]),
        "All 20 documents are tender notices; no award notice is stored.", plain_doc)
    unanswerable(
        "What payment term is recorded for '{title}'?".format(title=plain_doc["title"]),
        "The chunk text for this notice contains no payment term, and the prices table is empty.", plain_doc)

    # A document can contribute several facts in one pass; trim each category back
    # to its target so the totals are exact. Trimming keeps the earliest
    # (most frequently verifiable) questions in each category.
    kept: dict[str, int] = {}
    trimmed: list[Question] = []
    for question in questions:
        if kept.get(question.category, 0) >= TARGETS[question.category]:
            continue
        kept[question.category] = kept.get(question.category, 0) + 1
        trimmed.append(question)
    questions = trimmed

    counts = {category: sum(1 for q in questions if q.category == category) for category in TARGETS}
    print("counts:", counts, "total:", len(questions))
    missing = {category: TARGETS[category] - counts[category] for category in TARGETS if counts[category] != TARGETS[category]}
    if missing:
        raise SystemExit(f"Category targets not met: {missing}")

    OUT_DIR.mkdir(parents=True, exist_ok=True)
    created = datetime.now(UTC).isoformat()
    dataset = {
        "name": "epi-benchmark-120",
        "version": "3.0.0",
        "created": created,
        "corpus": corpus,
        "generator": "scripts/build_benchmark_v3.py",
        "labelling": (
            "Answers are read from the stored page text, the original HTML files, procurement_records and the "
            "graph store. No label was produced by the answer pipeline. 'auto_verified' means the evidence "
            "quote matched programmatically; it does not mean a human approved the question. No label has been "
            "human-adjudicated."
        ),
        "questions": [question.as_dict() for question in questions],
    }
    (OUT_DIR / "questions.json").write_text(json.dumps(dataset, indent=2, ensure_ascii=False), encoding="utf-8")

    manifest = {
        "dataset": "epi-benchmark-120",
        "version": "3.0.0",
        "created": created,
        "corpus": corpus,
        "counts": counts,
        "by_answerability": {
            key: sum(1 for q in questions if q.answerability == key)
            for key in ("answerable", "unanswerable", "needs_review")
        },
        "by_review_status": {
            key: sum(1 for q in questions if q.review_status == key)
            for key in ("auto_verified", "pending_review", "human_reviewed")
        },
        "verification": {
            key: sum(1 for q in questions if q.verification.get("method") == key)
            for key in sorted({q.verification.get("method") for q in questions})
        },
        "documents": [
            {
                "document_id": fact["document_id"],
                "filename": fact["filename"],
                "source_uri": fact["source_uri"],
                "page_count": fact["page_count"],
                "parsed_fields": sorted(k for k, v in fact.items() if v and k not in {"page_text"}),
            }
            for fact in parsed
        ],
        "items": [
            {
                "id": q.id,
                "category": q.category,
                "source_document_id": q.source_document_id,
                "supporting_section": q.supporting_section,
                "answerability": q.answerability,
                "review_status": q.review_status,
                "verification": q.verification,
            }
            for q in questions
        ],
    }
    (OUT_DIR / "ground_truth_manifest.json").write_text(
        json.dumps(manifest, indent=2, ensure_ascii=False), encoding="utf-8"
    )
    print(f"wrote {OUT_DIR / 'questions.json'} and ground_truth_manifest.json")
    print(json.dumps(dataset["corpus"], indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
